import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ __forceinline__ int floor_div(int a, int b) {
    int q = a / b;
    int r = a % b;
    if (r != 0 && ((r < 0) != (b < 0))) q--;
    return q;
}
__device__ __forceinline__ void load_chunk_to_smem(
    const float* __restrict__ weight,
    const float* __restrict__ input,
    float* __restrict__ s_weight_buf,
    float* __restrict__ s_input_buf,
    const int tid, const int block_threads,
    const int c0, const int chunk_size,
    const int k3, const int OC_TILE,
    const int ic_start, const int oc_local_start, const int out_channels_per_group,
    const int id_val_min, const int ih_val_min, const int iw_val_min,
    const int ID_TILE, const int IH_TILE, const int IW_TILE,
    const int in_channels, const int in_d, const int in_h, const int in_w,
    const int b)
{
    const int weight_chunk_elems = chunk_size * k3 * OC_TILE;
    for (int i = tid; i < weight_chunk_elems; i += block_threads) {
        const int per_ic = k3 * OC_TILE;
        const int ic_local = i / per_ic;
        const int rem = i % per_ic;
        const int oc_j = rem / k3;
        const int krem = rem % k3;
        const int ic = ic_start + c0 + ic_local;
        const int oc_local = oc_local_start + oc_j;
        float wv = 0.0f;
        if (oc_local < out_channels_per_group) {
            long long weight_idx = (((long long)ic * out_channels_per_group + oc_local) * k3) + krem;
            wv = weight[weight_idx];
        }
        s_weight_buf[(ic_local * OC_TILE + oc_j) * k3 + krem] = wv;
    }
    const int input_chunk_elems = chunk_size * ID_TILE * IH_TILE * IW_TILE;
    for (int i = tid; i < input_chunk_elems; i += block_threads) {
        int rem = i;
        const int iw_off = rem % IW_TILE; rem /= IW_TILE;
        const int ih_off = rem % IH_TILE; rem /= IH_TILE;
        const int id_off = rem % ID_TILE; rem /= ID_TILE;
        const int ic_local = rem;
        const int ic = ic_start + c0 + ic_local;
        const int id_val = id_val_min + id_off;
        const int ih_val = ih_val_min + ih_off;
        const int iw_val = iw_val_min + iw_off;
        float v = 0.0f;
        if (id_val >= 0 && id_val < in_d && ih_val >= 0 && ih_val < in_h && iw_val >= 0 && iw_val < in_w) {
            long long input_idx = (((long long)b * in_channels + ic) * in_d + id_val) * in_h * in_w
                                   + (long long)ih_val * in_w + iw_val;
            v = input[input_idx];
        }
        s_input_buf[i] = v;
    }
}
__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int in_d, const int in_h, const int in_w,
    const int out_d, const int out_h, const int out_w,
    const int kernel_size,
    const int stride,
    const int padding,
    const int groups,
    const int in_channels_per_group,
    const int out_channels_per_group,
    const bool has_bias,
    const int tiles_d, const int tiles_h, const int tiles_w,
    const int ID_TILE, const int IH_TILE, const int IW_TILE,
    const int oc_tiles_per_group)
{
    // Cooperative CTA-level spatial tiling with output-channel register blocking
    // and double-buffered (software-pipelined) shared-memory staging: while the
    // current input/weight chunk is being consumed from shared memory, the next
    // chunk's global loads are already issued into the alternate buffer, letting
    // memory latency overlap with the FMA-heavy accumulation loop.
    const int TILE_OD = 8, TILE_OH = 8, TILE_OW = 8;
    const int CHUNK_C = 8;
    const int OC_TILE = 8;
    extern __shared__ float smem[];
    const int k3 = kernel_size * kernel_size * kernel_size;
    const int size_weight = CHUNK_C * k3 * OC_TILE;
    const int size_input = CHUNK_C * ID_TILE * IH_TILE * IW_TILE;
    float* s_weight[2];
    float* s_input[2];
    s_weight[0] = smem;
    s_input[0] = smem + size_weight;
    s_weight[1] = smem + size_weight + size_input;
    s_input[1] = smem + 2 * size_weight + size_input;
    int bc = blockIdx.y;
    int total_oc_tiles = groups * oc_tiles_per_group;
    int b = bc / total_oc_tiles;
    int rem_bc = bc % total_oc_tiles;
    int g = rem_bc / oc_tiles_per_group;
    int oc_tile_idx = rem_bc % oc_tiles_per_group;
    int oc_local_start = oc_tile_idx * OC_TILE;
    int ic_start = g * in_channels_per_group;
    int tile_linear = blockIdx.x;
    int tw_idx = tile_linear % tiles_w;
    int th_idx = (tile_linear / tiles_w) % tiles_h;
    int td_idx = tile_linear / (tiles_w * tiles_h);
    int od0 = td_idx * TILE_OD;
    int oh0 = th_idx * TILE_OH;
    int ow0 = tw_idx * TILE_OW;
    int tid = threadIdx.x;
    int tw = tid % TILE_OW;
    int trest = tid / TILE_OW;
    int th = trest % TILE_OH;
    int td = trest / TILE_OH;
    int od = od0 + td;
    int oh = oh0 + th;
    int ow = ow0 + tw;
    bool valid_out = (od < out_d) && (oh < out_h) && (ow < out_w);
    int id_num_min = od0 + padding - (kernel_size - 1);
    int ih_num_min = oh0 + padding - (kernel_size - 1);
    int iw_num_min = ow0 + padding - (kernel_size - 1);
    int id_val_min = floor_div(id_num_min, stride);
    int ih_val_min = floor_div(ih_num_min, stride);
    int iw_val_min = floor_div(iw_num_min, stride);
    float sum[OC_TILE];
#pragma unroll
    for (int j = 0; j < OC_TILE; j++) sum[j] = 0.0f;
    const int num_chunks = (in_channels_per_group + CHUNK_C - 1) / CHUNK_C;
    {
        int chunk_size0 = min(CHUNK_C, in_channels_per_group - 0);
        load_chunk_to_smem(weight, input, s_weight[0], s_input[0],
            tid, blockDim.x, 0, chunk_size0, k3, OC_TILE,
            ic_start, oc_local_start, out_channels_per_group,
            id_val_min, ih_val_min, iw_val_min,
            ID_TILE, IH_TILE, IW_TILE,
            in_channels, in_d, in_h, in_w, b);
    }
    __syncthreads();
    for (int chunk_idx = 0; chunk_idx < num_chunks; chunk_idx++) {
        int c0 = chunk_idx * CHUNK_C;
        int chunk_size = min(CHUNK_C, in_channels_per_group - c0);
        int cur_buf = chunk_idx & 1;
        int next_buf = cur_buf ^ 1;
        if (chunk_idx + 1 < num_chunks) {
            int next_c0 = (chunk_idx + 1) * CHUNK_C;
            int next_chunk_size = min(CHUNK_C, in_channels_per_group - next_c0);
            load_chunk_to_smem(weight, input, s_weight[next_buf], s_input[next_buf],
                tid, blockDim.x, next_c0, next_chunk_size, k3, OC_TILE,
                ic_start, oc_local_start, out_channels_per_group,
                id_val_min, ih_val_min, iw_val_min,
                ID_TILE, IH_TILE, IW_TILE,
                in_channels, in_d, in_h, in_w, b);
        }
        if (valid_out) {
            float* cw = s_weight[cur_buf];
            float* ci = s_input[cur_buf];
            for (int ic_local = 0; ic_local < chunk_size; ic_local++) {
                for (int kd = 0; kd < kernel_size; kd++) {
                    int id_num = od + padding - kd;
                    if (id_num % stride != 0) continue;
                    int id_val = id_num / stride;
                    if (id_val < 0 || id_val >= in_d) continue;
                    int id_off = id_val - id_val_min;
                    for (int kh = 0; kh < kernel_size; kh++) {
                        int ih_num = oh + padding - kh;
                        if (ih_num % stride != 0) continue;
                        int ih_val = ih_num / stride;
                        if (ih_val < 0 || ih_val >= in_h) continue;
                        int ih_off = ih_val - ih_val_min;
                        for (int kw = 0; kw < kernel_size; kw++) {
                            int iw_num = ow + padding - kw;
                            if (iw_num % stride != 0) continue;
                            int iw_val = iw_num / stride;
                            if (iw_val < 0 || iw_val >= in_w) continue;
                            int iw_off = iw_val - iw_val_min;
                            int s_in_idx = ((ic_local * ID_TILE + id_off) * IH_TILE + ih_off) * IW_TILE + iw_off;
                            float in_val = ci[s_in_idx];
                            int krem = kd * kernel_size * kernel_size + kh * kernel_size + kw;
                            int s_w_base = ic_local * OC_TILE * k3 + krem;
#pragma unroll
                            for (int oc_j = 0; oc_j < OC_TILE; oc_j++) {
                                sum[oc_j] += in_val * cw[s_w_base + oc_j * k3];
                            }
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    if (valid_out) {
#pragma unroll
        for (int oc_j = 0; oc_j < OC_TILE; oc_j++) {
            int oc_local = oc_local_start + oc_j;
            if (oc_local >= out_channels_per_group) continue;
            int oc = g * out_channels_per_group + oc_local;
            float s = sum[oc_j];
            if (has_bias) {
                s += bias[oc];
            }
            long long out_idx = (((long long)b * out_channels + oc) * out_d + od) * out_h * out_w
                                 + (long long)oh * out_w + ow;
            output[out_idx] = s;
        }
    }
}
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int in_d = input.size(2);
    const int in_h = input.size(3);
    const int in_w = input.size(4);
    const int kernel_size = weight.size(2);
    const int out_channels_per_group = weight.size(1);
    const int out_channels = out_channels_per_group * groups;
    const int in_channels_per_group = in_channels / groups;
    const int out_d = (in_d - 1) * stride - 2 * padding + kernel_size + output_padding;
    const int out_h = (in_h - 1) * stride - 2 * padding + kernel_size + output_padding;
    const int out_w = (in_w - 1) * stride - 2 * padding + kernel_size + output_padding;
    auto output = torch::zeros({batch_size, out_channels, out_d, out_h, out_w}, input.options());
    const int TILE_OD = 8, TILE_OH = 8, TILE_OW = 8;
    const int CHUNK_C = 8;
    const int OC_TILE = 8;
    const int tiles_d = (out_d + TILE_OD - 1) / TILE_OD;
    const int tiles_h = (out_h + TILE_OH - 1) / TILE_OH;
    const int tiles_w = (out_w + TILE_OW - 1) / TILE_OW;
    const int id_span = TILE_OD - 1 + (kernel_size - 1);
    const int ih_span = TILE_OH - 1 + (kernel_size - 1);
    const int iw_span = TILE_OW - 1 + (kernel_size - 1);
    const int ID_TILE = id_span / stride + 2;
    const int IH_TILE = ih_span / stride + 2;
    const int IW_TILE = iw_span / stride + 2;
    const int threads = TILE_OD * TILE_OH * TILE_OW;
    const int oc_tiles_per_group = (out_channels_per_group + OC_TILE - 1) / OC_TILE;
    const long long blocks_x = (long long)tiles_d * tiles_h * tiles_w;
    const long long blocks_y = (long long)batch_size * groups * oc_tiles_per_group;
    dim3 grid((unsigned int)blocks_x, (unsigned int)blocks_y, 1);
    dim3 block(threads, 1, 1);
    const int k3 = kernel_size * kernel_size * kernel_size;
    const size_t shared_mem_size = (size_t)2 * (CHUNK_C * k3 * OC_TILE + CHUNK_C * ID_TILE * IH_TILE * IW_TILE) * sizeof(float);
    if (shared_mem_size > 49152) {
        cudaFuncSetAttribute(conv_transpose3d_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shared_mem_size);
    }
    const float* bias_ptr = nullptr;
    if (has_bias) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }
    conv_transpose3d_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_d, in_h, in_w,
        out_d, out_h, out_w,
        kernel_size,
        stride,
        padding,
        groups,
        in_channels_per_group,
        out_channels_per_group,
        has_bias,
        tiles_d, tiles_h, tiles_w,
        ID_TILE, IH_TILE, IW_TILE,
        oc_tiles_per_group
    );
    return output;
}
'''

conv_transpose3d_header = r'''
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups,
    bool has_bias);
'''

conv_transpose3d_module = load_inline(
    name='conv_transpose3d_module',
    cpp_sources=conv_transpose3d_header,
    cuda_sources=conv_transpose3d_source,
    functions=['conv_transpose3d_cuda'],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution with square input and square kernel,
    using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.has_bias = bias

        # Weight shape matching nn.ConvTranspose3d: (in_channels, out_channels/groups, kD, kH, kW)
        self.weight = nn.Parameter(torch.empty(in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        if self.bias is not None:
            fan_in = self.in_channels
            bound = 1 / (fan_in ** 0.5) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()
        bias_tensor = self.bias.cuda().contiguous() if self.has_bias else torch.empty(0, device=x.device)

        return conv_transpose3d_module.conv_transpose3d_cuda(
            x, weight, bias_tensor,
            self.stride, self.padding, self.output_padding, self.groups, self.has_bias
        )

